import{M as e,U as t,W as n,it as r}from"./chunks/framework.B6iJhav1.js";var i=JSON.parse(`{"title":"用户协议","description":"","frontmatter":{},"headers":[],"relativePath":"tos.md","filePath":"tos.md","lastUpdated":1786873544000}`),a={name:`tos.md`};function o(e,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[n(`<h1 id="tos" tabindex="-1">用户协议 <a class="header-anchor" href="#tos" aria-label="Permalink to “用户协议”">​</a></h1><p>感谢您使用“子悦机器”聊天机器人。在使用前，请仔细阅读本协议。调用子悦机器的命令即视为您已充分理解并接受本协议的全部条款。</p><h2 id="obligations" tabindex="-1">用户义务 <a class="header-anchor" href="#obligations" aria-label="Permalink to “用户义务”">​</a></h2><ol><li>自觉抵制不文明行为，践行体现社会主义核心价值观、符合社会主义道德和公序良俗、引领风尚、推动进步的行为；</li><li>自觉遵守第三方服务的用户协议（另见 <a href="#third-parties">第三方服务列表</a>）；</li><li>自觉遵守代码许可协议，维护子悦机器的开源生态；</li><li>禁止利用子悦机器从事违法违规、违反公序良俗和文明行为规范的活动；</li><li>禁止利用子悦机器，或对子悦机器进行逆向工程、数据抓取等破坏计算机信息系统的行为；</li><li>禁止利用子悦机器生成或传播违法、侵权、虚假信息；</li><li>禁止未经允许利用子悦机器进行广告投送；</li><li>禁止教唆或指使子悦机器违反所在社区的规则。</li></ol><h2 id="privacy" tabindex="-1">隐私条款 <a class="header-anchor" href="#privacy" aria-label="Permalink to “隐私条款”">​</a></h2><p>子悦机器作为个人信息的处理者，会遵循合法、正当、必要和诚信的原则。</p><p>子悦机器会出于服务维护和统计分析的目的，收集并存储包括但不限于以下信息：</p><ol><li>聊天平台的用户 ID 和昵称；</li><li>调用命令的时间及参数列表；</li><li>特定命令相关的持久性数据（<a href="/ZiYueBot/general/driftbottle/">漂流云瓶</a>、<a href="/ZiYueBot/general/straitbottle/">海峡云瓶</a>）。</li></ol><p>请您了解，随着我们业务的发展，可能会对功能和提供的服务有所调整变化。原则上，当新功能或服务与我们当前提供的功能或服务相关时，收集与使用的个人信息将与原处理目的具有直接或合理关联。</p><h2 id="termination" tabindex="-1">终止条款 <a class="header-anchor" href="#termination" aria-label="Permalink to “终止条款”">​</a></h2><p><em>另见：<a href="/ZiYueBot/technical/blacklists">黑名单</a></em></p><p>如果您违反了子悦机器的用户协议，我们有权终止您部分命令或所有命令的使用权（黑名单）。</p><p>黑名单一般是永久的，后续是否解禁取决于违反协议的严重程度。</p><h2 id="third-parties" tabindex="-1">第三方服务列表 <a class="header-anchor" href="#third-parties" aria-label="Permalink to “第三方服务列表”">​</a></h2><p>目前包含第三方服务的命令有：<a href="/ZiYueBot/general/chat">对话</a>、<a href="/ZiYueBot/general/draw">绘画</a>。</p><ol><li>千问: <a href="https://terms.alicdn.com/legal-agreement/terms/c_end_product_protocol/20231011201348415/20231011201348415.html" target="_blank" rel="noreferrer">服务协议</a>、<a href="https://terms.alicdn.com/legal-agreement/terms/privacy_policy_full/20231011201849846/20231011201849846.html" target="_blank" rel="noreferrer">隐私政策</a></li><li>阿里云百炼：<a href="https://terms.alicdn.com/legal-agreement/terms/common_platform_service/20230728213935489/20230728213935489.html" target="_blank" rel="noreferrer">服务协议</a></li></ol>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};